import sys

def doctorStrange(N, M, arr):
    if N <= 1:
        return 0

    adj = [[] for _ in range(N + 1)]
    for u, v in arr:
        adj[u].append(v)
        adj[v].append(u)

    disc = [-1] * (N + 1)
    low = [-1] * (N + 1)
    parent = [-1] * (N + 1)
    ap = [False] * (N + 1)
    timer = 0

    def dfs(u):
        nonlocal timer
        disc[u] = low[u] = timer
        timer += 1
        children = 0

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] != -1 and low[v] >= disc[u]:
                    ap[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

        if parent[u] == -1 and children > 1:
            ap[u] = True

    for i in range(1, N + 1):
        if disc[i] == -1:
            dfs(i)

    count = sum(1 for i in range(1, N + 1) if ap[i])
    return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    arr = []
    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            arr.append((u, v))
        except StopIteration:
            break

    result = doctorStrange(N, M, arr)
    print(result)

if __name__ == "__main__":
    main()
